from typing import Dict, Any, Optional, Type
import importlib
import inspect
import sys
import logging
from tools.base import BaseTool

logging.basicConfig(
    level=logging.ERROR,
    format='%(levelname)s: %(message)s'
)


class ToolExecutor:
    """
    Encapsulates dynamic tool loading, instantiation, and execution.
    Provides uniform error handling and result formatting.
    """

    def __init__(self, tools_package_name: str = "tools"):
        self.tools_package_name = tools_package_name
        self._module_cache: Dict[str, Any] = {}

    def execute(self, tool_name: str, tool_input: Dict[str, Any]) -> Dict[str, Any]:
        """
        Execute a tool by name with given input.

        Args:
            tool_name: The name of the tool to execute (matches module name)
            tool_input: Dictionary of arguments to pass to the tool's execute method

        Returns:
            Dict with 'success', 'result', and optionally 'error' keys
        """
        try:
            # Load module (using cache to avoid reload overhead)
            module = self._load_module(tool_name)
            if module is None:
                return {
                    'success': False,
                    'error': f"Failed to import tool module: tools.{tool_name}"
                }

            # Find tool instance
            tool_instance = self._find_tool_instance_in_module(module, tool_name)
            if tool_instance is None:
                return {
                    'success': False,
                    'error': f"Tool class not found matching name '{tool_name}' in module 'tools.{tool_name}'"
                }

            # Execute tool
            result = tool_instance.execute(**tool_input)
            return {'success': True, 'result': result}

        except Exception as e:
            logging.error(f"Tool execution error for '{tool_name}': {str(e)}")
            return {
                'success': False,
                'error': f"Error executing tool '{tool_name}': {str(e)}"
            }

    def _load_module(self, tool_name: str) -> Optional[Any]:
        """
        Load a tool module by name, using cache to avoid redundant imports.

        Args:
            tool_name: The name of the tool (module name without 'tools.' prefix)

        Returns:
            The loaded module, or None if import fails
        """
        module_name = f"{self.tools_package_name}.{tool_name}"

        # Return cached module if available
        if module_name in self._module_cache:
            return self._module_cache[module_name]

        try:
            # Clear any cached module to allow fresh import on refresh
            if module_name in sys.modules:
                del sys.modules[module_name]

            module = importlib.import_module(module_name)
            self._module_cache[module_name] = module
            return module
        except ImportError as e:
            logging.error(f"Import error for module '{module_name}': {str(e)}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error loading module '{module_name}': {str(e)}")
            return None

    def _find_tool_instance_in_module(self, module, tool_name: str) -> Optional[BaseTool]:
        """
        Search a given module for a tool class matching tool_name and return an instance of it.

        Args:
            module: The module to search
            tool_name: The name of the tool to find

        Returns:
            An instance of the matching tool class, or None if not found
        """
        for name, obj in inspect.getmembers(module):
            if (inspect.isclass(obj) and 
                issubclass(obj, BaseTool) and 
                obj != BaseTool):
                try:
                    tool_instance = obj()
                    if tool_instance.name == tool_name:
                        return tool_instance
                except Exception as init_err:
                    logging.error(f"Error initializing tool {name}: {str(init_err)}")

        return None


