    def _clean_string_for_display(data: str) -> str:
        """Clean a string for display by handling base64 data."""
        if len(data) > 1000 and ';base64,' in data:
            return "[base64 data omitted]"
        return data

    @staticmethod
    def _clean_data_for_display(data):
        """
        Recursively clean data structures for display, replacing large base64 content.
        """
        if isinstance(data, dict):
            cleaned = {}
            for key, value in data.items():
                # Handle image data in various formats
                if key in ['data', 'image', 'source'] and isinstance(value, str):
                    if len(value) > 1000 and (';base64,' in value or value.startswith('data:')):
                        cleaned[key] = "[base64 data omitted]"
                    else:
                        cleaned[key] = value
                else:
                    cleaned[key] = ToolResultFormatter._clean_data_for_display(value)
            return cleaned
        elif isinstance(data, list):
            return [ToolResultFormatter._clean_data_for_display(item) for item in data]
        elif isinstance(data, str) and len(data) > 1000 and ';base64,' in data:
            return "[base64 data omitted]"
        return data
